  const row = contentRow(parts, cat, o.minH || 40);
  const w = Math.max(o.minW || 0, Math.ceil(row.width));
  const { d, H, top } = pathStatement(w, row.height, o);
  holder.appendChild(shapeVector(d, cat, 'Shape', o.ghost));
  holder.appendChild(row);
  row.x = 0; row.y = top;
