  spacer(dh, 1, true);
  inst('Connection Status', { Status: connected && prof === 'RoboCore V2' ? 'Connected' : 'Disconnected' }, dh, { name: 'Connection' });
  const db = box({ name: 'Detail body', dir: 'H', gap: 32, cross: 'center', parent: dc, wSize: 'fill' });
