// ============================================================================
// 07 — Behaviour Spec: every control, what it must do, and where to try it in
// the prototype (one row = one test case), plus the Blockly / Monaco handoff.
// The same data is written to docs/behaviour-spec.md by tools/spec_md.js.
// ============================================================================

function specTable(parent, cols, rows, o = {}) {
  const t = box({ name: o.name || 'Table', dir: 'V', gap: 0, radius: 10, clip: true, stroke: 'color/border/default', parent });
  const hr = box({ name: 'Header row', dir: 'H', gap: 0, fill: 'color/ink/default', parent: t });
  for (const [title, w] of cols) {
    const c = box({ name: 'Head ' + title, dir: 'V', pad: [10, 12, 10, 12], w, parent: hr });
    txt(title, { style: 'Label/Strong', color: 'color/text/on-ink', parent: c, name: 'Text', fill: true });
  }
  rows.forEach((r, i) => {
    const row = box({ name: 'Row ' + (r[0] || i + 1), dir: 'H', gap: 0, fill: i % 2 ? 'color/bg/app' : 'color/bg/panel', parent: t });
    r.forEach((cell, j) => {
      const c = box({ name: 'Cell', dir: 'V', gap: 4, pad: [9, 12, 9, 12], w: cols[j][1], parent: row, hSize: 'fill' });
      if (cell === '☐') { inst('Checkbox', { Checked: 'False' }, c, { name: 'Pass' }); return; }
      const mono = o.mono && o.mono.indexOf(j) >= 0;
      txt(String(cell), { style: j === 0 && o.strong !== false ? 'Label/Strong' : (mono ? 'Code/Small' : 'Body/Small'), color: j === 0 ? 'color/text/primary' : 'color/text/secondary', parent: c, name: 'Text', fill: true });
    });
  });
  return t;
}
function buildSpecPage(page) {
  const root = box({ name: 'Behaviour spec', dir: 'V', gap: 40, pad: 64, w: 1640, fill: 'color/bg/app', parent: page });
  root.x = 0; root.y = 0;
  const hd = box({ name: 'Header', dir: 'V', gap: 10, parent: root, wSize: 'fill' });
  txt('Behaviour spec & handoff', { style: 'Heading/Display', parent: hd, name: 'Title' });
  txt('Every control in the RoboCore IDE, what it must do, and where to try it in the prototype (page 05). Each row is a test case: run it in the prototype now, and on the built app later. Blocks are Google Blockly; the code editor is Monaco.', { style: 'Body/Default', color: 'color/text/secondary', parent: hd, name: 'Intro', w: 1200 });
  const total = SPEC.reduce((a, s) => a + s.rows.length, 0);
  txt(total + ' test cases in ' + SPEC.length + ' areas · IDs are stable: add new rows at the end of an area.', { style: 'Caption/Default', color: 'color/text/tertiary', parent: hd, name: 'Count' });
  for (const s of SPEC) {
    const sec = box({ name: 'Area — ' + s.area, dir: 'V', gap: 14, pad: 28, fill: 'color/bg/panel', radius: 14, stroke: 'color/border/default', parent: root, wSize: 'fill' });
    const h = box({ name: 'Area header', dir: 'H', gap: 12, cross: 'center', parent: sec });
    const b = inst('Badge', { Tone: 'Ink' }, h, { name: 'Area id' }); setText(b, 'Label', s.id);
    txt(s.area, { style: 'Heading/H1', parent: h, name: 'Title' });
    const rows = s.rows.map((r, i) => [s.id + '-' + String(i + 1).padStart(2, '0'), r[0], r[1], r[2], r[3], '☐']);
    specTable(sec, [['ID', 80], ['Control', 230], ['Do', 280], ['Expect', 520], ['Prototype', 300], ['Pass', 74]], rows, { name: 'Tests ' + s.id, mono: [4] });
  }
  const ho = box({ name: 'Handoff', dir: 'V', gap: 18, pad: 28, fill: 'color/bg/panel', radius: 14, stroke: 'color/border/default', parent: root, wSize: 'fill' });
  txt('Handoff · Blockly theme and workspace', { style: 'Heading/H1', parent: ho, name: 'Title' });
  specTable(ho, [['Setting', 320], ['Value', 560], ['Note', 600]], HANDOFF.blocklyTheme, { name: 'Blockly', mono: [1] });
  txt('Block catalogue · ' + BLOCK_LIBRARY.length + ' blocks', { style: 'Heading/H1', parent: ho, name: 'Title Blocks' });
  txt('What each block says, its shape, the Arduino C++ it generates, and what the RoboCore library needs (“add …” = a helper to write first). Notation: [dropdown] (number) “text” < > empty yes / no slot.', { style: 'Body/Small', color: 'color/text/secondary', parent: ho, name: 'Blocks intro', w: 1200 });
  specTable(ho, [['Category', 140], ['Block', 370], ['Shape', 100], ['Generates (C++)', 420], ['RoboCore library', 426]], blockCatalogueRows(), { name: 'Block catalogue', mono: [3] });
  txt('Handoff · Monaco theme and options', { style: 'Heading/H1', parent: ho, name: 'Title Monaco' });
  specTable(ho, [['Setting', 320], ['Value', 560], ['Note', 600]], HANDOFF.monaco, { name: 'Monaco', mono: [1] });
  txt('Implementation notes', { style: 'Heading/H1', parent: ho, name: 'Title Notes' });
  specTable(ho, [['Topic', 320], ['Note', 1160]], HANDOFF.notes, { name: 'Notes' });
  txt('What the Figma prototype cannot do', { style: 'Heading/H1', parent: ho, name: 'Title Limits' });
  specTable(ho, [['Limit', 320], ['Why and what to do', 1160]], PROTO_LIMITS, { name: 'Limits' });
  REPORT.counts.specRows = total;
  return root;
}
// ============================================================================
// Orchestration: guard → pages → tokens → components → foundations → screens
// → prototype → (optional) PNG export to a local review server
// ============================================================================

async function preparePages() {
  const managed = Object.values(PAGE_NAMES);
  for (const p of figma.root.children) await p.loadAsync();
  const foreign = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length > 0);
  if (foreign.length) throw new Error('This file already has other content (page "' + foreign[0].name + '"). Run the builder in a new, empty design file.');
  // never wipe generated pages by accident: that needs the explicit Rebuild command
  const built = figma.root.children.filter(p => managed.indexOf(p.name) >= 0 && p.children.length > 0);
  if (built.length && figma.command !== 'rebuild') throw new Error('This file already has the generated pages. Use Plugins → Development → RoboCore IDE Design Builder → Rebuild to regenerate them (manual edits on those pages are replaced; version history keeps the old version).');
  const pages = {};
  // rename an empty default page to Foundations
  const empties = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length === 0);
  for (const [key, name] of Object.entries(PAGE_NAMES)) {
    let p = figma.root.children.find(x => x.name === name);
    if (!p && empties.length) { p = empties.shift(); p.name = name; }
    if (!p) { p = figma.createPage(); p.name = name; }
    pages[key] = p;
  }
  // order pages 01..05
  Object.values(PAGE_NAMES).forEach((name, i) => { const p = figma.root.children.find(x => x.name === name); if (p) figma.root.insertChild(i, p); });
  // remove leftover empty pages
  for (const p of figma.root.children.slice()) if (managed.indexOf(p.name) < 0 && p.children.length === 0 && figma.root.children.length > 5) p.remove();
  // clear managed pages (re-run safety: everything here is generated)
  for (const p of Object.values(pages)) for (const c of p.children.slice()) c.remove();
  return pages;
}

function waitForUI(type, ms) {
  return new Promise((resolve) => {
    const t = setTimeout(() => { figma.ui.off('message', h); resolve(null); }, ms);
    const h = (msg) => { if (msg && msg.type === type) { clearTimeout(t); figma.ui.off('message', h); resolve(msg); } };
    figma.ui.on('message', h);
  });
}
let UI_OPEN = false;
async function openReview() {
  if (!UI_OPEN) { figma.showUI(__html__, { visible: false, width: 240, height: 80 }); UI_OPEN = true; }
  for (let i = 0; i < 4; i++) {
    figma.ui.postMessage({ type: 'ping' });
    const pong = await waitForUI('pong', 3000);
    if (pong && pong.ok) return true;
  }
  return false;
}
async function exportForReview(items) {
  let n = 0;
  for (const [name, node, scale] of items) {
    if (!node || node.removed) continue;
    try {
      const bytes = await node.exportAsync({ format: 'PNG', constraint: { type: 'SCALE', value: scale } });
      figma.ui.postMessage({ type: 'png', name, bytes });
      await waitForUI('ack', 20000);
      n++;
    } catch (e) { warn('export ' + name + ': ' + e.message); }
  }
  REPORT.exported = (REPORT.exported || 0) + n;
}
async function sendReport() {
  try {
    figma.ui.postMessage({ type: 'report', report: REPORT });
    await waitForUI('ack', 8000);
  } catch (e) { /* UI not open */ }
}

async function main() {
  const T = Date.now();
  const mark = (k) => { REPORT.timings[k] = Date.now() - T; };
  const pages = await preparePages();
  mark('pages');
  await setupFonts();
  await setupTokens();
  mark('tokens');

  await figma.setCurrentPageAsync(pages.components);
  await buildComponentsPage(pages.components);
  await applyLinks();
  mark('components');

  await figma.setCurrentPageAsync(pages.foundations);
  buildFoundations(pages.foundations);
  await applyLinks();
  mark('foundations');

  await figma.setCurrentPageAsync(pages.ide);
  const IDE = buildIdePage(pages.ide);
  await applyLinks();
  mark('ide');
  await yieldUI();

  await figma.setCurrentPageAsync(pages.screens);
  const SCR = buildScreensPage(pages.screens);
  await applyLinks();
  mark('screens');
  await yieldUI();

  await figma.setCurrentPageAsync(pages.prototype);
  await buildPrototype(pages.prototype, IDE, SCR);
  mark('prototype');

  await figma.setCurrentPageAsync(pages.dark);
  const DK = await buildDarkPage(pages.dark, IDE, SCR);
  mark('dark');

  // page canvas backgrounds
  for (const p of Object.values(pages)) p.backgrounds = [{ type: 'SOLID', color: hexToRgb(p === pages.dark ? '#0B1422' : '#E9E2D2') }];

  REPORT.counts.ideFrames = Object.keys(IDE).length;
  REPORT.counts.screenFrames = Object.keys(SCR).length;

  // optional: export PNGs for review (only if the local review server answers)
  const review = await openReview();
  REPORT.export = review ? 'on' : 'skipped (no local review server)';
  if (review) {
    await figma.setCurrentPageAsync(pages.ide);
    const items = [];
    for (const [k, f] of Object.entries(IDE)) items.push(['ide_' + k + '.png', f, 1]);
    for (const [k, f] of Object.entries(SCR)) items.push(['screen_' + k + '.png', f, 1]);
    await exportForReview(items);
    await figma.setCurrentPageAsync(pages.components);
    const comps = pages.components.children[0];
    if (comps) await exportForReview(comps.children.map(fam => ['comp_' + fam.name.replace(/[^\w]+/g, '_') + '.png', fam, 0.6]));
    await figma.setCurrentPageAsync(pages.foundations);
    const fnd = pages.foundations.children[0];
    if (fnd) await exportForReview(fnd.children.map(sec => ['found_' + sec.name.replace(/[^\w]+/g, '_') + '.png', sec, 0.6]));
    await figma.setCurrentPageAsync(pages.prototype);
    await exportForReview(pages.prototype.children.filter(c => c.type === 'FRAME').slice(0, 3).map(c => ['proto_' + c.name.replace(/[^\w]+/g, '_') + '.png', c, 0.5]));
    await figma.setCurrentPageAsync(pages.dark);
    await exportForReview(Object.entries(DK).map(([k, f]) => ['dark_' + k + '.png', f, 1]).concat([['dark_guide.png', pages.dark.children.find(c => c.name === 'Dark mode guide'), 0.6]]));
  }
  REPORT.timings.total = Date.now() - T;
  await sendReport();
  await figma.setCurrentPageAsync(pages.foundations);
  figma.viewport.scrollAndZoomIntoView(pages.foundations.children);
}

main().then(() => {
  const msg = 'RoboCore IDE design built — ' + (REPORT.errors.length ? REPORT.errors.length + ' error(s), ' : '') + (REPORT.counts.icons || 0) + ' icons, ' + (REPORT.counts.blocks || 0) + ' blocks, ' + ((REPORT.counts.ideFrames || 0) + (REPORT.counts.screenFrames || 0)) + ' screens';
  figma.closePlugin(msg);
}).catch(async (e) => {
  REPORT.errors.push('FATAL: ' + (e && e.message ? e.message : String(e) + ' (' + typeof e + ')') + ' | ' + ((e && e.stack) || '').split('\n').slice(0, 6).join(' | '));
  try { if (await openReview()) await sendReport(); } catch (x) { /* ignore */ }
  figma.closePlugin('RoboCore IDE builder stopped: ' + (e && e.message ? e.message : String(e)));
});
